const p = document.getElementById('complex-paragraph');
if (!p) return false;
const isEnabled = p.classList.contains('ai4a11y-simplified');
if (!isEnabled) {
  return !p.querySelector('.ai4a11y-toggle-original') &&
         !p.querySelector('.ai4a11y-text-content');
}
const text = p.querySelector('.ai4a11y-text-content');
const orig = p.querySelector('.ai4a11y-original-content');
const btn = p.querySelector('.ai4a11y-toggle-original');
return !!text && !!orig && !!btn &&
       text.textContent === 'The recipient has the right to quickly cancel access privileges if it becomes necessary.' &&
       btn.textContent === 'Show original' &&
       orig.style.display === 'none';

const btn = document.querySelector('.ai4a11y-toggle-original');
const isEnabled = !!btn;
if (!isEnabled) return true;
btn.focus();
const focused = document.activeElement === btn;
const rect = btn.getBoundingClientRect();
btn.blur();
return focused && rect.width >= 24 && rect.height >= 24 && btn.tagName === 'BUTTON';

const p = document.getElementById('complex-paragraph');
if (!p) return false;
const btn = p.querySelector('.ai4a11y-toggle-original');
const isEnabled = !!btn;
if (!isEnabled) return true;
const text = p.querySelector('.ai4a11y-text-content');
const orig = p.querySelector('.ai4a11y-original-content');

// Click to show original
btn.click();
const showingOriginal = orig.style.display !== 'none' && text.style.display === 'none' && btn.textContent === 'Show simplified';
if (!showingOriginal) return false;

// Click to show simplified again (puts the page back)
btn.click();
btn.blur();
const showingSimplified = orig.style.display === 'none' && text.style.display === '' && btn.textContent === 'Show original';
return showingSimplified;

const article = document.getElementById('long-content');
if (!article) return false;
const isEnabled = article.dataset.ai4a11ySummarize === 'done';
if (!isEnabled) return !article.querySelector('.ai4a11y-summary-box');
const box = article.querySelector('.ai4a11y-summary-box');
if (!box) return false;
const hasRegion = box.getAttribute('role') === 'region' && box.getAttribute('aria-label') === 'Summary';
const content = box.querySelector('.ai4a11y-summary-content');
return hasRegion && !!content && content.textContent.includes('subscriber rights to contest billing discrepancies');

const shortP = document.getElementById('short-paragraph');
const table = document.getElementById('fee-table');
if (!shortP || !table) return false;
return shortP.textContent.includes('This is a simple notice.') &&
       !shortP.classList.contains('ai4a11y-simplified') &&
       !table.querySelector('.ai4a11y-summary-box') &&
       !table.classList.contains('ai4a11y-simplified');

